namespace RonSijm.FluidHumidifier.Factories.EMR;

public class NotebookExecutionFactory(string resourceName = null, Action<Humidifier.EMR.NotebookExecution> factoryAction = null) : ResourceFactory<Humidifier.EMR.NotebookExecution>(resourceName)
{

    internal InnerNotebookExecutionExecutionEngineConfigFactory ExecutionEngineFactory { get; set; }

    internal InnerNotebookExecutionNotebookS3LocationFactory NotebookS3LocationFactory { get; set; }

    internal InnerNotebookExecutionOutputNotebookS3LocationFactory OutputNotebookS3LocationFactory { get; set; }

    protected override Humidifier.EMR.NotebookExecution Create()
    {
        var notebookExecutionResult = CreateNotebookExecution();
        factoryAction?.Invoke(notebookExecutionResult);

        return notebookExecutionResult;
    }

    private Humidifier.EMR.NotebookExecution CreateNotebookExecution()
    {
        var notebookExecutionResult = new Humidifier.EMR.NotebookExecution
        {
            GivenName = InputResourceName,
        };

        return notebookExecutionResult;
    }
    public override void CreateChildren(Humidifier.EMR.NotebookExecution result)
    {
        base.CreateChildren(result);

        result.ExecutionEngine ??= ExecutionEngineFactory?.Build();
        result.NotebookS3Location ??= NotebookS3LocationFactory?.Build();
        result.OutputNotebookS3Location ??= OutputNotebookS3LocationFactory?.Build();
    }

} // End Of Class

